//! noevia#1318 slice 12: native `GET /api/v1/sections/{name}/draft-heads` through the real router.
//!
//! On Linux every case of `fixtures/draft-heads-python.v1.json` (the actual services Python,
//! regenerated by CI from the pinned ref) runs through the router and the kernel-contained
//! opener, against a fake Hub giving the recorded answers: status, content type, body and the Hub
//! requests must match. Elsewhere that opener refuses by design (the native 503), which is
//! asserted instead; the lib tests run the same cases on every platform. Routes the native read
//! does not own reach the Python child. Every name is synthetic.
#![cfg(feature = "native-draft-heads")]
#![allow(
    clippy::unwrap_used,
    clippy::expect_used,
    clippy::panic,
    clippy::indexing_slicing
)]
use axum::{
    body::Body,
    http::{Method, Request},
};
use http_body_util::BodyExt;
use noevia_model_manager::{
    draft_heads::{DraftHeads, REFUSAL},
    draft_heads_route, Container, DockerRead, Redactor, StateData,
};
use serde_json::{json, Value};
use std::{
    future::Future,
    path::{Path, PathBuf},
    pin::Pin,
    sync::{Arc, Mutex},
};
use tokio::io::{AsyncReadExt, AsyncWriteExt};
use tower::ServiceExt;

const TOKEN: &str = "synthetic-model-loader-token-0123456789abcdef";

type Job<'a, T> = Pin<Box<dyn Future<Output = Result<T, &'static str>> + Send + 'a>>;

struct NoDocker;

impl DockerRead for NoDocker {
    fn containers(&self) -> Job<'_, Vec<Container>> {
        Box::pin(async { Err("not used") })
    }
    fn logs<'a>(&'a self, _: &'a str, _: usize) -> Job<'a, Vec<u8>> {
        Box::pin(async { Err("not used") })
    }
}

fn state(heads: Option<DraftHeads>, legacy_base: &str) -> Arc<StateData> {
    Arc::new(StateData {
        #[cfg(feature = "native-diagnose")]
        diagnosis: None,
        #[cfg(feature = "native-prompts")]
        prompts: None,
        #[cfg(feature = "native-settings")]
        settings: None,
        model_updates: None,
        model_detail: None,
        sections: None,
        embedding: None,
        host: None,
        token: TOKEN.into(),
        configured: vec![],
        docker: Arc::new(NoDocker),
        redactor: Redactor::new().unwrap(),
        permits: tokio::sync::Semaphore::new(4),
        legacy: noevia_model_manager::legacy_client().unwrap(),
        legacy_base: legacy_base.into(),
        idle_unload: None,
        #[cfg(feature = "native-download-targets")]
        download_targets: None,
        #[cfg(feature = "native-badges")]
        badges: None,
        #[cfg(feature = "native-bench-runs")]
        bench_runs: None,
        #[cfg(feature = "native-section-writes")]
        section_writes: None,
        #[cfg(feature = "native-settings-write")]
        settings_write: None,
        #[cfg(feature = "native-benchmark-overview")]
        benchmark_overview: None,
        #[cfg(feature = "native-check-updates")]
        check_updates: None,
        #[cfg(feature = "native-downloads")]
        downloads: None,
        #[cfg(feature = "native-model-delete")]
        model_delete: None,
        draft_heads: heads.map(Arc::new),
        #[cfg(feature = "native-search")]
        search: None,
        #[cfg(feature = "native-backends")]
        backend_stats: None,
        #[cfg(feature = "native-benchmark-runner")]
        bench_runner: None,
        #[cfg(feature = "native-backend-control")]
        backends: None,
    })
}

async fn call(state: Arc<StateData>, method: &str, uri: &str) -> (u16, Option<String>, String) {
    let request = Request::builder()
        .method(method)
        .uri(uri)
        .header("x-model-loader-token", TOKEN)
        .body(Body::empty())
        .unwrap();
    let response = noevia_model_manager::router(state)
        .oneshot(request)
        .await
        .unwrap();
    let status = response.status().as_u16();
    let kind = response
        .headers()
        .get("content-type")
        .map(|v| v.to_str().unwrap().to_owned());
    let bytes = response.into_body().collect().await.unwrap().to_bytes();
    (status, kind, String::from_utf8(bytes.to_vec()).unwrap())
}

fn closed_port() -> String {
    let closed = std::net::TcpListener::bind("127.0.0.1:0").unwrap();
    let base = format!("http://127.0.0.1:{}", closed.local_addr().unwrap().port());
    drop(closed);
    base
}

#[test]
fn route_shapes() {
    let get = Method::GET;
    for (path, name) in [
        ("/api/v1/sections/m/draft-heads", Some("m")),
        ("/api/v1/sections/a%20b/draft-heads", Some("a b")),
        ("/api/v1/sections/%C3%BC/draft-heads", Some("\u{fc}")),
        ("/api/v1/sections/%ZZ/draft-heads", Some("%ZZ")),
        ("/api/v1/sections/%FF/draft-heads", Some("\u{fffd}")),
        ("/api/v1/sections/a%2Fb/draft-heads", None),
        ("/api/v1/sections/a/b/draft-heads", None),
        ("/api/v1/sections//draft-heads", None),
        ("/api/v1/sections/m/draft-heads/", None),
        ("/api/v1/sections/m/draft-heads/download", None),
        ("/api/v1/sections/m", None),
    ] {
        assert_eq!(draft_heads_route(&get, path).as_deref(), name, "{path}");
    }
    for method in [Method::POST, Method::HEAD, Method::PUT, Method::DELETE] {
        assert_eq!(
            draft_heads_route(&method, "/api/v1/sections/m/draft-heads"),
            None
        );
    }
}

/// Another method answers FastAPI's 405 (the front's route policy); a slash in the name and the
/// draft-head download are forwarded (here to a closed port: 502).
#[tokio::test(flavor = "multi_thread", worker_threads = 2)]
async fn unowned_requests_are_not_answered_natively() {
    let dir = tempfile::tempdir().unwrap();
    let heads = DraftHeads::new(dir.path(), &dir.path().join("models.ini"), dir.path()).unwrap();
    let shared = state(Some(heads), &closed_port());
    for (method, uri, expected) in [
        ("POST", "/api/v1/sections/m/draft-heads", 405),
        ("GET", "/api/v1/sections/a%2Fb/draft-heads", 502),
        ("POST", "/api/v1/sections/m/draft-heads/download", 502),
    ] {
        let (status, _, body) = call(shared.clone(), method, uri).await;
        assert_eq!(status, expected, "{method} {uri}: {body}");
        assert!(!body.contains(REFUSAL), "{method} {uri}");
    }
}

fn gguf_bytes(kv: &serde_json::Map<String, Value>) -> Vec<u8> {
    let mut out = b"GGUF".to_vec();
    out.extend(3u32.to_le_bytes());
    out.extend(0u64.to_le_bytes());
    out.extend((kv.len() as u64).to_le_bytes());
    for (key, spec) in kv {
        out.extend((key.len() as u64).to_le_bytes());
        out.extend(key.as_bytes());
        let value = &spec[1];
        match spec[0].as_str().unwrap() {
            "str" => {
                let v = value.as_str().unwrap();
                out.extend(8u32.to_le_bytes());
                out.extend((v.len() as u64).to_le_bytes());
                out.extend(v.as_bytes());
            }
            "u32" => {
                out.extend(4u32.to_le_bytes());
                out.extend(
                    u32::try_from(value.as_u64().unwrap())
                        .unwrap()
                        .to_le_bytes(),
                );
            }
            "i32" => {
                out.extend(5u32.to_le_bytes());
                out.extend(
                    i32::try_from(value.as_i64().unwrap())
                        .unwrap()
                        .to_le_bytes(),
                );
            }
            "f32" => {
                out.extend(6u32.to_le_bytes());
                #[allow(clippy::cast_possible_truncation)]
                out.extend((value.as_f64().unwrap() as f32).to_le_bytes());
            }
            "bool" => {
                out.extend(7u32.to_le_bytes());
                out.push(u8::from(value.as_bool().unwrap()));
            }
            "u64" => {
                out.extend(10u32.to_le_bytes());
                out.extend(value.as_u64().unwrap().to_le_bytes());
            }
            other => panic!("{other}"),
        }
    }
    out
}

fn build(root: &Path, case: &Value) -> PathBuf {
    let models = root.join("models");
    std::fs::create_dir(&models).unwrap();
    for spec in case["files"].as_array().unwrap() {
        let path = models.join(spec["name"].as_str().unwrap());
        std::fs::create_dir_all(path.parent().unwrap()).unwrap();
        if let Some(kv) = spec.get("gguf") {
            std::fs::write(&path, gguf_bytes(kv.as_object().unwrap())).unwrap();
        } else {
            let file = std::fs::File::create(&path).unwrap();
            file.set_len(spec["size"].as_u64().unwrap()).unwrap();
        }
    }
    for link in case["links"].as_array().into_iter().flatten() {
        std::os::unix::fs::symlink(
            link[1].as_str().unwrap(),
            models.join(link[0].as_str().unwrap()),
        )
        .unwrap();
    }
    if let Some(ini) = case["ini"].as_str() {
        std::fs::write(models.join("models.ini"), ini).unwrap();
    }
    models
}

fn store(data: &Path, schema: &Value, case: &Value) {
    let db = rusqlite::Connection::open(data.join("model_loader.db")).unwrap();
    for sql in schema.as_array().unwrap() {
        db.execute_batch(sql.as_str().unwrap()).unwrap();
    }
    db.execute("DELETE FROM kv", []).unwrap();
    for sql in case["seed"].as_array().into_iter().flatten() {
        db.execute_batch(sql.as_str().unwrap()).unwrap();
    }
}

type Seen = Arc<Mutex<Vec<Value>>>;

fn hex(text: &str) -> Vec<u8> {
    (0..text.len())
        .step_by(2)
        .map(|i| u8::from_str_radix(&text[i..i + 2], 16).unwrap())
        .collect()
}

async fn hub(answers: Value) -> (String, Seen, tokio::task::JoinHandle<()>) {
    let listener = tokio::net::TcpListener::bind("127.0.0.1:0").await.unwrap();
    let base = format!("http://127.0.0.1:{}", listener.local_addr().unwrap().port());
    let seen: Seen = Arc::new(Mutex::new(Vec::new()));
    let (b, s) = (base.clone(), seen.clone());
    let task = tokio::spawn(async move {
        while let Ok((mut sock, _)) = listener.accept().await {
            let (answers, base, seen) = (answers.clone(), b.clone(), s.clone());
            tokio::spawn(async move {
                let mut head = Vec::new();
                let mut byte = [0u8; 1];
                while !head.ends_with(b"\r\n\r\n") {
                    if sock.read(&mut byte).await.unwrap_or(0) == 0 {
                        return;
                    }
                    head.push(byte[0]);
                }
                let text = String::from_utf8_lossy(&head).into_owned();
                let mut lines = text.split("\r\n");
                let path = lines.next().unwrap().split(' ').nth(1).unwrap().to_owned();
                let auth = lines
                    .filter_map(|l| l.split_once(':'))
                    .find(|(k, _)| k.eq_ignore_ascii_case("authorization"))
                    .map(|(_, v)| Value::String(v.trim().to_owned()))
                    .unwrap_or(Value::Null);
                seen.lock()
                    .unwrap()
                    .push(json!({"path": path, "authorization": auth}));
                let (status, headers, body) = match answers.get(&path) {
                    Some(a) => (
                        a["status"].as_u64().unwrap(),
                        a["headers"].as_array().unwrap().clone(),
                        hex(a["body"].as_str().unwrap()),
                    ),
                    None => (
                        404,
                        vec![json!(["content-type", "application/json"])],
                        br#"{"error":"Repository not found"}"#.to_vec(),
                    ),
                };
                let mut out = format!("HTTP/1.1 {status} X\r\n");
                for h in headers {
                    out.push_str(&format!(
                        "{}: {}\r\n",
                        h[0].as_str().unwrap(),
                        h[1].as_str().unwrap().replace("@HUB@", &base)
                    ));
                }
                out.push_str(&format!(
                    "content-length: {}\r\nconnection: close\r\n\r\n",
                    body.len()
                ));
                let _ = sock.write_all(out.as_bytes()).await;
                let _ = sock.write_all(&body).await;
                let _ = sock.shutdown().await;
            });
        }
    });
    (base, seen, task)
}

#[tokio::test(flavor = "multi_thread", worker_threads = 2)]
async fn actual_python_differential_through_the_router() {
    let fixture: Value =
        serde_json::from_str(include_str!("fixtures/draft-heads-python.v1.json")).unwrap();
    let mut compared = 0;
    for case in fixture["cases"].as_array().unwrap() {
        let id = case["id"].as_str().unwrap();
        let dir = tempfile::tempdir().unwrap();
        let root = dir.path().canonicalize().unwrap();
        let models = build(&root, case);
        store(&root, &fixture["schema"], case);
        let answers = case.get("hub").cloned().unwrap_or(json!({}));
        let (base, seen, server) = hub(answers).await;
        let heads = DraftHeads::with_hub(
            &models,
            &models.join("models.ini"),
            &root,
            &format!("{base}/api"),
        )
        .unwrap();
        let shared = state(Some(heads), &closed_port());
        for expected in case["results"].as_array().unwrap() {
            seen.lock().unwrap().clear();
            let name = expected["name"].as_str().unwrap();
            let uri = format!("/api/v1/sections/{name}/draft-heads");
            let (status, kind, body) = call(shared.clone(), "GET", &uri).await;
            let ctx = format!("{id} {name}");
            if cfg!(target_os = "linux") {
                assert_eq!(
                    u64::from(status),
                    expected["status"].as_u64().unwrap(),
                    "{ctx}: {body}"
                );
                assert_eq!(kind.as_deref(), expected["content_type"].as_str(), "{ctx}");
                assert_eq!(body, expected["body"].as_str().unwrap(), "{ctx}");
                assert_eq!(
                    Value::Array(seen.lock().unwrap().clone()),
                    expected["requests"],
                    "{ctx}"
                );
                compared += 1;
            } else {
                assert_eq!(status, 503, "{ctx}: {body}");
                assert_eq!(body, json!({ "detail": REFUSAL }).to_string(), "{ctx}");
                assert!(seen.lock().unwrap().is_empty(), "{ctx}");
            }
        }
        server.abort();
    }
    if cfg!(target_os = "linux") {
        assert!(compared >= 40, "{compared}");
    }
}
